    private fun <T> verifyCompatibility(
        serializer: KSerializer<T>,
        expected: T,
        protobuf: String,
        defaultsProtobuf: String = protobuf,
        native: String? = null,
    ): T {
        // Given
        val previousBytes = protobuf.fromHexToByteArray()
        val previousDefaultsBytes = defaultsProtobuf.fromHexToByteArray()

        // When
        val decoded = ProtoBuf.decodeFromByteArray(serializer, previousBytes)
        val decodedDefaults = defaults.decodeFromByteArray(serializer, previousDefaultsBytes)
        val encoded = ProtoBuf.encodeToByteArray(serializer, expected)
        val encodedDefaults = defaults.encodeToByteArray(serializer, expected)

        // Then
        assertEquals(expected, decodedDefaults)
        assertContentEquals(previousBytes, encoded)
        assertContentEquals(previousDefaultsBytes, encodedDefaults)
        if (native != null) {
            assertContentEquals(native.fromHexToByteArray(), (decoded as AttoSerializable).toByteArray())
            assertContentEquals(native.fromHexToByteArray(), (decodedDefaults as AttoSerializable).toByteArray())
        }
        return decoded
    }
